import time

def throttle(wait_time):
    """A decorator to throttle a function call to once every `wait_time` seconds."""
    def decorator(func):
        last_called = 0  # Initialize the last call time to 0 (no previous call)

        def wrapper(*args, **kwargs):
            nonlocal last_called
            now = time.time()

            # If a previous call has been made and it was within the cooldown period
            if last_called != 0 and now - last_called < wait_time:
                raise Exception("Rate limit exceeded: Function can only be called once per minute.")

            # Update last call time and proceed
            last_called = now
            return func(*args, **kwargs)

        return wrapper
    return decorator

@throttle(wait_time=60)
def process_data():
    print("Processing data...")

# First call - allowed
process_data()

# Second call within 60 seconds - will raise an exception
try:
    process_data()
except Exception as e:
    print(e)  # Output: "Rate limit exceeded: Function can only be called once per minute."

# Third call after more than 60 seconds - allowed
time.sleep(61)
process_data()

