import time

def throttle(interval: float = 60.0):
    """Throttle a function to run no more than once per given interval (in seconds)."""
    def decorator(func):
        last_call = 0.0

        def wrapper(*args, **kwargs):
            nonlocal last_call
            current_time = time.time()
            if current_time - last_call > interval:
                last_call = current_time
                return func(*args, **kwargs)
            return None  # Optionally, return None or log a message for throttled calls

        return wrapper

    return decorator

