def column_stats(table):
    def mean(data):
        return sum(data) / len(data)

    def median(data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 1:
            return sorted_data[mid]
        else:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2

    def mode(data):
        counts = {}
        max_count = 0
        mode_val = None
        for num in data:
            counts[num] = counts.get(num, 0) + 1
            if counts[num] > max_count:
                max_count = counts[num]
                mode_val = num
        return mode_val

    def variance(data):
        mean_val = mean(data)
        return sum((x - mean_val) ** 2 for x in data) / len(data)

    headers = table[0]
    data_rows = table[1:]
    result = {}

    for i in range(len(headers)):
        column_data = [row[i] for row in data_rows]
        result[headers[i]] = {
            'mean': mean(column_data),
            'median': median(column_data),
            'mode': mode(column_data),
            'variance': variance(column_data)
        }

    return result

