import sys

def main():
    # Read input and split into words
    labels = [s.strip() for s in sys.stdin.read().split() if s.strip()]

    # Determine unique labels in order of first occurrence
    unique_labels = []
    label_to_index = {}

    for label in labels:
        if label not in label_to_index:
            label_to_index[label] = len(unique_labels)
            unique_labels.append(label)

    # Build the one-hot encoded matrix
    matrix = []
    for label in labels:
        row = [0] * len(unique_labels)
        row[label_to_index[label]] = 1
        matrix.append(row)

    # Print the matrix
    for row in matrix:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()

