import sys

def main():
    # Read input lines and strip leading/trailing whitespace
    labels = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            labels.append(line)

    # Determine unique categories in the order of first occurrence
    unique_labels = []
    for label in labels:
        if label not in unique_labels:
            unique_labels.append(label)

    # One-hot encode each label
    result = []
    for label in labels:
        vec = [0] * len(unique_labels)
        idx = unique_labels.index(label)
        vec[idx] = 1
        result.append(vec)

    # Print the one-hot encoded matrix
    for row in result:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()

