from typer import Typer, Argument, Option
import importlib

app = Typer()

@app.command()
def watch(
    file: str,
    callback: str,
    module: str = None,
    func: str = None
):
    """
    Watch a file for modifications and trigger a callback.

    If callback is a Python function in a module, specify the module and function name.
    If it's a command, it will be executed via subprocess.
    """

    if module and func:
        # Handle Python function callback
        try:
            module = importlib.import_module(module)
            callback_func = getattr(module, func)
            callback_func()
        except (ImportError, AttributeError) as e:
            raise ValueError(f"Invalid module or function: {e}")
    else:
        # Handle command-line callback
        subprocess.run(callback, shell=True, check=True)

    class FileChangeHandler(FileSystemEventHandler):
        def on_modified(self, event):
            if event.src_path == file:
                # Re-run the callback (or the function)
                if module and func:
                    try:
                        module = importlib.import_module(module)
                        callback_func = getattr(module, func)
                        callback_func()
                    except Exception as e:
                        print(f"Error in Python callback: {e}")
                else:
                    try:
                        subprocess.run(callback, shell=True, check=True)
                    except Exception as e:
                        print(f"Error in command callback: {e}")

    # Run watch
    event_handler = FileChangeHandler()
    observer = Observer()
    observer.schedule(event_handler, path=os.path.dirname(file), recursive=False)
    observer.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

