import time
import subprocess

def watch_file(args):
    file_path = args.file
    callback = args.callback
    interval = args.interval

    # Validate that the file exists
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file {file_path} does not exist.")

    last_mtime = os.path.getmtime(file_path)
    print(f"Watching file '{file_path}' for changes... (interval: {interval}s)")

    try:
        while True:
            time.sleep(interval)
            current_mtime = os.path.getmtime(file_path)

            if current_mtime != last_mtime:
                last_mtime = current_mtime
                print(f"File '{file_path}' has been modified. Triggering callback...")

                # Execute the callback
                try:
                    subprocess.run(callback, shell=True, check=True)
                except subprocess.CalledProcessError as e:
                    print(f"Error in callback: {e}")
                except Exception as e:
                    print(f"Unexpected error during callback: {e}")
    except KeyboardInterrupt:
        print("\nMonitoring stopped.")

