import click
import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
import subprocess
import os

@click.command()
@click.argument('file_path')
@click.argument('command')
def watch_file(file_path, command):
    """
    Watch a specific file and run the given command when it is modified.
    """
    # Validate that the file exists
    if not os.path.exists(file_path):
        click.echo(f"Error: File '{file_path}' does not exist.", err=True)
        return

    class FileChangeHandler(FileSystemEventHandler):
        def on_modified(self, event):
            if event.src_path == file_path:
                click.echo(f"File {file_path} has been modified.")
                try:
                    subprocess.run(command, shell=True, check=True)
                except subprocess.CalledProcessError as e:
                    click.echo(f"Error running command: {e}", err=True)

    # Setup the observer
    event_handler = FileChangeHandler()
    observer = Observer()
    observer.schedule(event_handler, path=file_path, recursive=False)
    observer.start()

    try:
        click.echo(f"Watching file: {file_path}")
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        click.echo("\nStopping file watcher...")
        observer.stop()
    observer.join()

import urllib.request
from html.parser import HTMLParser

class LinkExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            for attr in attrs:
                if attr[0] == 'href':
                    self.links.append(attr[1])

def extract_links(html_content):
    """Extracts all 'href' attributes from <a> tags in the provided HTML content."""
    parser = LinkExtractor()
    parser.feed(html_content)
    return parser.links


def fetch_html(url):
    """Fetches HTML content from the given URL using urllib.request."""
    try:
        with urllib.request.urlopen(url) as response:
            return response.read().decode('utf-8')
    except urllib.error.URLError as e:
        raise RuntimeError(f"Failed to fetch URL: {e.reason}")
    except Exception as e:
        raise RuntimeError(f"An error occurred while fetching the URL: {e}")

