def watch_file(
    path: str | Path,
    callback: callable,
) -> None:
    """Watch a file path for changes and trigger the callback when it changes.

    Args:
        path: A string or Path object representing the file or directory to watch.
        callback: A function that will be called when the file is modified.
    """
    class FileChangeHandler(FileSystemEventHandler):
        def on_modified(self, event):
            if event.src_path == str(path):
                callback()

    event_handler = FileChangeHandler()
    observer = Observer()
    observer.schedule(event_handler, path=str(path), recursive=False)
    observer.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

