function throttle(func) {
  let lastExecutionTime = Date.now() - 60000 * 2;

  return function throttledFunction() {
    const now = Date.now();
    const elapsed = now - lastExecutionTime;

    if (elapsed >= 60000) {
      func.apply(this, arguments);
      lastExecutionTime = now;
    }
  };
}

function logMessage() {
  console.log("Throttled function called at:", Date.now());
}

const throttled = throttle(logMessage);

throttled(); // This runs
throttled(); // Ignored
throttled(); // Ignored
throttled(); // This runs after 1 minute

/**
 * Throttles a function so that it only executes once per minute.
 * @param {Function} func - The function to be throttled.
 * @returns {Function} A wrapped function that runs the original function only once per minute.
 */
function throttle(func) {
  let lastCallTime = 0;

  return function (...args) {
    const now = Date.now();

    // Only allow the function to run if at least 60 seconds have passed
    if (now - lastCallTime >= 60000) {
      func(...args);
      lastCallTime = now;
    }
  };
}

