throttledLog("Second message"); // Ignored (within 1 minute)
throttledLog("Third message");  // Ignored (within 1 minute)

// Wait 60 seconds and then try again
setTimeout(() => {
  throttledLog("After 1 minute"); // Runs
}, 60000);

function throttle(func) {
  let lastExecutionTime = null;

  return function(...args) {
    const now = Date.now();

    if (lastExecutionTime === null || now - lastExecutionTime > 60000) {
      func.apply(this, args);
      lastExecutionTime = now;
    }
  };
}

// Example function to throttle
function logMessage() {
  console.log("Message logged at:", new Date().toLocaleTimeString());
}

// Throttle the function
const throttledLog = throttle(logMessage);

// Call it multiple times rapidly
for (let i = 0; i < 10; i++) {
  throttledLog();
}

