import sys
from collections import defaultdict

def main():
    try:
        n = int(sys.stdin.read().strip())
    except ValueError:
        print("Invalid input. Please enter a valid integer.")
        return

    n_abs = abs(n)

    if n_abs == 1:
        print("1")
        return

    factors = []
    current_n = n_abs
    d = 2

    while d * d <= current_n:
        while current_n % d == 0:
            factors.append(d)
            current_n //= d
        d += 1

    if current_n > 1:
        factors.append(current_n)

    counts = defaultdict(int)
    for factor in factors:
        counts[factor] += 1

    sorted_factors = sorted(counts.keys())

    result = []
    for factor in sorted_factors:
        if counts[factor] == 1:
            result.append(str(factor))
        else:
            result.append(f"{factor}^{counts[factor]}")

    print(" * ".join(result))

