def topo_sort(pairs):
    # Step 1: Identify all unique nodes (tasks and dependencies)
    nodes = set()
    for task, dep in pairs:
        nodes.add(task)
        nodes.add(dep)

    if not nodes:
        return []

    # Step 2: Build the graph (adjacency list)
    adj = defaultdict(list)
    indegree = {node: 0 for node in nodes}

    for task, dep in pairs:
        adj[dep].append(task)
        indegree[task] += 1

    # Step 3: Initialize queue with nodes having zero in-degree
    queue = deque()
    for node in nodes:
        if indegree[node] == 0:
            queue.append(node)

    # Step 4: Perform Kahn's algorithm
    result = []
    while queue:
        current = queue.popleft()
        result.append(current)
        for neighbor in adj[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # Step 5: Check for cycle
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

