def parse_log_line(line):
    # Regex to match YYYY-MM-DD HH:MM:SS as the first part of the log line
    timestamp_pattern = r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) (.*)'
    match = re.match(timestamp_pattern, line.strip())

    if not match:
        return False

    date_str, message = match.groups()

    try:
        # Parse the timestamp
        dt = datetime.datetime.strptime(date_str, "%Y-%m-%d %H:%M:%S")
        return {
            "timestamp": dt.isoformat(),
            "message": message
        }
    except ValueError:
        return False

