def prime_factors(n):
    if n <= 1:
        return []

    factors = []

    # Handle the case for 2 (even number)
    count = 0
    while n % 2 == 0:
        count += 1
        n //= 2
    if count > 0:
        factors.append((2, count))

    # Check for odd divisors from 3 upwards
    i = 3
    while i * i <= n:
        count = 0
        while n % i == 0:
            count += 1
            n //= i
        if count > 0:
            factors.append((i, count))
        i += 2

    # If the remaining n is a prime number greater than 1
    if n > 1:
        factors.append((n, 1))

    return factors

