import time

def throttle(seconds):
    def decorator(func):
        def wrapper(*args, **kwargs):
            now = time.time()
            # Check if the function has been called before and if the elapsed time is at least "seconds"
            if 'last_call_time' not in wrapper.__dict__ or now - wrapper.last_call_time >= seconds:
                wrapper.last_call_time = now
                return func(*args, **kwargs)
            else:
                return None  # Function call ignored
        return wrapper
    return decorator

import time

def throttle(interval):
    def decorator(func):
        last_called = None  # Track the last time the function was called

        def wrapper(*args, **kwargs):
            nonlocal last_called  # Access the variable from the outer scope
            now = time.time()  # Current time in seconds

            if last_called is None:
                # First call, always allow
                result = func(*args, **kwargs)
                last_called = now
                return result
            else:
                if now - last_called >= interval:
                    # Allow the function to run if it's been long enough since the last call
                    result = func(*args, **kwargs)
                    last_called = now
                    return result
        return wrapper
    return decorator

