from collections import deque

def group_points(points, radius, min_group_size):
    n = len(points)
    if n == 0:
        return []

    labels = [-1] * n
    visited = [False] * n
    cluster_id = 0

    radius_sq = radius * radius

    for i in range(n):
        if not visited[i]:
            queue = deque()
            queue.append(i)
            visited[i] = True
            component = [i]

            while queue:
                current = queue.popleft()

                # Check all other points
                for j in range(n):
                    if not visited[j]:
                        dx = points[current][0] - points[j][0]
                        dy = points[current][1] - points[j][1]
                        dist_sq = dx * dx + dy * dy

                        if dist_sq <= radius_sq:
                            visited[j] = True
                            queue.append(j)
                            component.append(j)

            # Check if component size is sufficient for a cluster
            if len(component) >= min_group_size:
                for idx in component:
                    labels[idx] = cluster_id
                cluster_id += 1

    return labels

