def prime_factors(
    n: int,
) -> list[int]:
    """Compute the prime factorisation of a given integer.

    Returns a list of prime factors, in ascending order.
    """
    factors = []
    if n <= 1:
        return factors
    # Handle the case of 2 separately
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    # Check odd numbers starting from 3
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2
    if n > 1:
        factors.append(n)
    return factors

