import re

def parse_log_lines(log_lines):
    # Regular expression pattern for log line with timestamp and message
    # Sample format: [YYYY-MM-DD HH:MM:SS] LEVEL: Message
    LOG_PATTERN = re.compile(
        r'^$$([0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2})$$ ([A-Z]+): (.*)$'
    )

    parsed_logs = []

    for line in log_lines:
        match = LOG_PATTERN.match(line.strip())
        if match:
            timestamp = match.group(1)
            level = match.group(2)
            message = match.group(3)
            parsed_logs.append({
                'timestamp': timestamp,
                'level': level,
                'message': message
            })

    return parsed_logs

