def one_hot_encode(labels):
    if not labels:
        return []

    unique_categories = []
    seen = set()

    for label in labels:
        if label not in seen:
            seen.add(label)
            unique_categories.append(label)

    label_to_index = {label: i for i, label in enumerate(unique_categories)}

    matrix = []
    for label in labels:
        vec = [0] * len(unique_categories)
        vec[label_to_index[label]] = 1
        matrix.append(vec)

    return matrix

import sys
from collections import defaultdict, deque

def main():
    edges = []
    nodes = set()

    # Read input and build the graph
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if not parts:
            continue

        task = parts[0]
        dependencies = parts[1:]

        nodes.add(task)
        for dep in dependencies:
            nodes.add(dep)
            edges.append((dep, task))  # dep → task

    # Build adjacency list and in-degree counter
    adj = defaultdict(list)
    in_degree = defaultdict(int)

    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1

    # Kahn's algorithm
    queue = deque()
    for node in nodes:
        if in_degree.get(node, 0) == 0:
            queue.append(node)

    top_order = []

    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check for cycles
    if len(top_order) != len(nodes):
        print("Cycle detected")
    else:
        print(' '.join(top_order))

