import math
from collections import deque

def distance(p1, p2):
    """Compute Euclidean distance between two points."""
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(p1, p2)))

def dbscan(points, eps, min_samples):
    """
    Perform density-based spatial clustering of applications with noise (DBSCAN).

    Args:
        points: list of tuples representing points (can be 2D, 3D, or more).
        eps: float, the radius of the neighborhood.
        min_samples: int, the minimum number of points in a neighborhood to form a cluster.

    Returns:
        A list of integers where each integer corresponds to the cluster label of each point.
        Noise points are labeled with -1.
    """
    if not points:
        return []

    n = len(points)
    cluster_label = [-1] * n  # -1 means noise
    visited = [False] * n
    cluster_id = 0

    for i in range(n):
        if not visited[i]:
            visited[i] = True
            neighbors = []
            # Find all neighbors within `eps` distance (including the point itself)
            for j in range(n):
                if distance(points[i], points[j]) <= eps:
                    neighbors.append(j)

            if len(neighbors) < min_samples:
                cluster_label[i] = -1
            else:
                cluster_id += 1
                queue = deque(neighbors)
                cluster_label[i] = cluster_id

                while queue:
                    current = queue.popleft()
                    if not visited[current]:
                        visited[current] = True
                        cluster_label[current] = cluster_id

                        # Find neighbors of current point
                        current_neighbors = []
                        for j in range(n):
                            if distance(points[current], points[j]) <= eps:
                                current_neighbors.append(j)

                        # Add unvisited neighbors to the queue
                        for neighbor in current_neighbors:
                            if not visited[neighbor]:
                                queue.append(neighbor)

    return cluster_label

