import zipfile
import tarfile
import os

def extract_archive(archive_path, return_data=False):
    """
    Extracts the contents of an archive file and returns filenames or file data.

    Args:
        archive_path (str): The path to the downloaded archive file.
        return_data (bool, optional): Whether to return the file content as Data (bytes).
                                     Defaults to False.

    Returns:
        list: If return_data is False: list of filenames (without paths)
              If return_data is True: list of tuples [(filename, content_bytes)]
    """

    # Normalize the file extension for case-insensitive comparison
    archive_path_lower = archive_path.lower()

    try:
        if archive_path_lower.endswith('.zip'):
            with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                if return_data:
                    content_list = []
                    for name in zip_ref.namelist():
                        content = zip_ref.read(name)
                        content_list.append((name, content))
                    return content_list
                else:
                    return zip_ref.namelist()

        elif archive_path_lower.endswith('.tar.gz') or archive_path_lower.endswith('.tgz'):
            with tarfile.open(archive_path, 'r:gz') as tar:
                if return_data:
                    content_list = []
                    for name in tar.getnames():
                        content = tar.extractfile(name).read()
                        content_list.append((name, content))
                    return content_list
                else:
                    return tar.getnames()

        elif archive_path_lower.endswith('.tar.bz2') or archive_path_lower.endswith('.tbz2'):
            with tarfile.open(archive_path, 'r:bz2') as tar:
                if return_data:
                    content_list = []
                    for name in tar.getnames():
                        content = tar.extractfile(name).read()
                        content_list.append((name, content))
                    return content_list
                else:
                    return tar.getnames()

        elif archive_path_lower.endswith('.tar.xz') or archive_path_lower.endswith('.txz'):
            with tarfile.open(archive_path, 'r:xz') as tar:
                if return_data:
                    content_list = []
                    for name in tar.getnames():
                        content = tar.extractfile(name).read()
                        content_list.append((name, content))
                    return content_list
                else:
                    return tar.getnames()

        elif archive_path_lower.endswith('.tar'):
            with tarfile.open(archive_path, 'r') as tar:
                if return_data:
                    content_list = []
                    for name in tar.getnames():
                        content = tar.extractfile(name).read()
                        content_list.append((name, content))
                    return content_list
                else:
                    return tar.getnames()

        else:
            raise ValueError(f"Unsupported archive format: {os.path.splitext(archive_path)[1]}")

    except Exception as e:
        raise RuntimeError(f"Error reading archive: {e}")

