def topological_sort(
    dependencies: list[tuple[str, str]],
) -> list[str]:
    """Return a valid execution order of tasks based on dependencies.

    Each dependency pair is (dependent, dependency), indicating that the dependent
    task depends on the dependency task. Returns a list of tasks in an order
    where each task is executed after its dependencies.

    Raises ValueError if there's a cycle in the dependencies.
    """
    nodes = set()
    for dependent, dependency in dependencies:
        nodes.add(dependent)
        nodes.add(dependency)

    if not nodes:
        return []

    # Build adjacency list and in_degrees
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for dependent, dependency in dependencies:
        adj[dependency].append(dependent)
        in_degree[dependent] += 1

    queue = deque(node for node in nodes if in_degree[node] == 0)
    order = []

    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != len(nodes):
        raise ValueError("Cycle detected in dependencies")

    return order

