def resolve_dependencies(
    dependencies: list[tuple[str, str]],
) -> list[str]:
    """Return a valid execution order of tasks given their dependencies.

    Each dependency pair is a tuple (task, depends_on), meaning task depends on
    depends_on. If there's a cycle, raises ValueError.
    """
    adjacency = defaultdict(list)
    in_degree = defaultdict(int)
    nodes = set()

    for task, depends_on in dependencies:
        nodes.add(task)
        nodes.add(depends_on)
        adjacency[depends_on].append(task)
        in_degree[task] += 1

    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    result = []
    while queue:
        current = queue.popleft()
        result.append(current)
        for neighbor in adjacency[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in dependencies")

    return result

