def topological_order(
    depends_on: list[tuple[str, str]],
) -> list[str]:
    """Return a valid execution order for tasks given their dependencies.

    Raises ValueError if there's a cycle.
    """
    adj = {}
    in_degrees = {}
    nodes = set()

    # Build graph
    for task, dep in depends_on:
        nodes.add(task)
        nodes.add(dep)
        if dep not in adj:
            adj[dep] = []
        adj[dep].append(task)
        if task not in in_degrees:
            in_degrees[task] = 0
        in_degrees[task] += 1

    # Initialize in_degrees for all nodes
    for node in nodes:
        if node not in in_degrees:
            in_degrees[node] = 0

    # Kahn's algorithm
    queue = deque()
    for node in nodes:
        if in_degrees[node] == 0:
            queue.append(node)

    result = []
    while queue:
        current = queue.popleft()
        result.append(current)
        for neighbor in adj.get(current, []):
            in_degrees[neighbor] -= 1
            if in_degrees[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected: cannot determine valid execution order.")

    return result
